-- Database MySQL Karua Areum | Import melalui phpMyAdmin

CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(80) NOT NULL, email VARCHAR(120) NOT NULL UNIQUE, hp VARCHAR(16) NULL, hash VARCHAR(255) NULL, peran ENUM('pelanggan','capster','kasir','admin') NOT NULL DEFAULT 'pelanggan') ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS layanan (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(150) NOT NULL, harga INT NULL, keterangan TEXT NULL, kategori VARCHAR(30) NOT NULL DEFAULT 'Rambut', durasi INT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS capster (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, id_user BIGINT UNSIGNED NULL, nama VARCHAR(100) NOT NULL, keahlian TEXT NULL, pengalaman TEXT NULL, foto TEXT NULL, aktif TINYINT(1) NOT NULL DEFAULT 1, CONSTRAINT fk_capster_user FOREIGN KEY(id_user) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS booking (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, kode VARCHAR(20) NOT NULL UNIQUE, id_pelanggan BIGINT UNSIGNED NULL, nama_pelanggan VARCHAR(80) NOT NULL, id_layanan BIGINT UNSIGNED NOT NULL, id_capster BIGINT UNSIGNED NOT NULL, tanggal DATE NOT NULL, jam TIME NOT NULL, status ENUM('menunggu','dikonfirmasi','selesai','batal') NOT NULL DEFAULT 'menunggu', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, catatan VARCHAR(300) NULL, id_tryon BIGINT UNSIGNED NULL, slot_aktif TINYINT GENERATED ALWAYS AS (CASE WHEN status <> 'batal' THEN 1 ELSE NULL END) STORED, UNIQUE KEY ux_booking_slot(id_capster,tanggal,jam,slot_aktif), CONSTRAINT fk_booking_user FOREIGN KEY(id_pelanggan) REFERENCES users(id) ON DELETE SET NULL, CONSTRAINT fk_booking_layanan FOREIGN KEY(id_layanan) REFERENCES layanan(id), CONSTRAINT fk_booking_capster FOREIGN KEY(id_capster) REFERENCES capster(id), INDEX idx_booking_tanggal(tanggal), INDEX idx_booking_capster_tanggal(id_capster,tanggal)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS libur (id_capster BIGINT UNSIGNED NOT NULL, tanggal DATE NOT NULL, PRIMARY KEY(id_capster,tanggal), CONSTRAINT fk_libur_capster FOREIGN KEY(id_capster) REFERENCES capster(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS promo (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, judul VARCHAR(150) NOT NULL, deskripsi TEXT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS produk (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(150) NOT NULL, deskripsi TEXT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS galeri (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, judul VARCHAR(150) NOT NULL, kategori VARCHAR(80) NULL, foto TEXT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS model_rambut (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(150) NOT NULL, gambar LONGTEXT NOT NULL, bentuk VARCHAR(150) NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tryon (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, id_user BIGINT UNSIGNED NOT NULL, gambar LONGTEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_tryon_user FOREIGN KEY(id_user) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pengaturan (kunci VARCHAR(80) PRIMARY KEY, nilai TEXT NULL) ENGINE=InnoDB;

-- Virtual Try-On AI (aditif; tidak mengubah tabel lama)
CREATE TABLE IF NOT EXISTS vto_hasil (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, id_user BIGINT UNSIGNED NOT NULL, gaya VARCHAR(80) NOT NULL, gambar VARCHAR(255) NULL, status ENUM('proses','selesai','gagal') NOT NULL DEFAULT 'proses', provider VARCHAR(40) NULL, pesan VARCHAR(300) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_vto_user FOREIGN KEY(id_user) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_vto_user(id_user, created_at)) ENGINE=InnoDB;

-- Pembayaran & catatan transaksi (FU-5)
CREATE TABLE IF NOT EXISTS transaksi (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, kode_order VARCHAR(40) NOT NULL UNIQUE, id_booking BIGINT UNSIGNED NULL, id_pelanggan BIGINT UNSIGNED NULL, nama_pelanggan VARCHAR(80) NOT NULL, layanan VARCHAR(150) NOT NULL, total INT NOT NULL, metode VARCHAR(30) NOT NULL, status ENUM('menunggu','berhasil','gagal','kedaluwarsa') NOT NULL DEFAULT 'menunggu', uang_diterima INT NULL, kembalian INT NULL, snap_url VARCHAR(300) NULL, id_kasir BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, paid_at TIMESTAMP NULL DEFAULT NULL, CONSTRAINT fk_trx_booking FOREIGN KEY(id_booking) REFERENCES booking(id) ON DELETE SET NULL, INDEX idx_trx_status(status, created_at), INDEX idx_trx_booking(id_booking)) ENGINE=InnoDB;
